async function activate(source, service, out, errors) {
  for await (const env of source) {                   // AsyncIterable<Envelope>
    try {
      const receipt = await service.place(env.payload);
      await out.send({ correlationId: env.correlationId, payload: receipt });
    } catch (err) {
      await errors.send({ env, err });                // never swallow: no implicit ack
    }
  }
}
